-- Dark Chaos - Ascension companion pet batch 1 (156 pets)
-- Pets that exist only in the Ascension 3.3.5a client (VanityCollection companion category; its
-- 'Sigil of ...' collectibles left out), deduplicated against DarkChaos by look and by name.
-- Generated by retroport_tools/dc_pet_ascension_pipeline.py from _asc_pets/plan.json.
-- dc_pet_definitions.expansion = 100 = Ascension; DC-Collection keys its filter on items 350000-359999.
-- IDs: spell/item 351000-351155 | creature 3466500-3466655 | display 507000-507155 | vendor slots 1879-2034 (NPC 3461229)

-- 1) creature_model_info
DELETE FROM `creature_model_info` WHERE `DisplayID` BETWEEN 507000 AND 507155;

-- 2) creature_template
DELETE FROM `creature_template` WHERE `entry` BETWEEN 3466500 AND 3466655;

-- 3) creature_template_model
DELETE FROM `creature_template_model` WHERE `CreatureID` BETWEEN 3466500 AND 3466655;

-- 4) item_template (class 15 / subclass 2; spellid_1 55884 trigger 0, spellid_2 summon trigger 6)
DELETE FROM `item_template` WHERE `entry` BETWEEN 351000 AND 351155;

-- 5) npc_vendor (Skeletal Petkeeper; dc_paged_collection_vendor pages the roster)
DELETE FROM `npc_vendor` WHERE `entry`=3461229 AND `item` BETWEEN 351000 AND 351155;
DELETE FROM `npc_vendor` WHERE `entry`=3461229 AND `slot` BETWEEN 1879 AND 2034;

-- 6) conditions cleanup
DELETE FROM `conditions` WHERE `SourceTypeOrReferenceId`=23 AND `SourceGroup`=3461229 AND `SourceEntry` BETWEEN 351000 AND 351155 AND `ConditionTypeOrReference`=25;

-- 7) dc_pet_definitions (pet_entry = item entry; rarity == item Quality; expansion 100)
DELETE FROM `dc_pet_definitions` WHERE `pet_entry` BETWEEN 351000 AND 351155;
ON DUPLICATE KEY UPDATE `name`=VALUES(`name`),`pet_spell_id`=VALUES(`pet_spell_id`),`source`=VALUES(`source`),`display_id`=VALUES(`display_id`),`rarity`=VALUES(`rarity`),`expansion`=VALUES(`expansion`),`variant_group`=VALUES(`variant_group`),`variant_color`=VALUES(`variant_color`);

-- 8) dc_collection_definitions (collection_type 2 = PET, entry_id = item entry)
DELETE FROM `dc_collection_definitions` WHERE `collection_type`=2 AND `entry_id` BETWEEN 351000 AND 351155;
